# ===== linked_list.py =====
"""Singly linked list module."""


class Node:
    """A single node holding a value and a reference to the next node."""

    def __init__(self, value, next=None):
        self.value = value
        self.next = next

    def __repr__(self):
        return f"Node({self.value!r})"


class LinkedList:
    """A singly linked list."""

    def __init__(self):
        self.head = None
        self._size = 0

    def __len__(self):
        return self._size

    def __iter__(self):
        node = self.head
        while node is not None:
            yield node.value
            node = node.next

    def to_list(self):
        """Return the values as a regular Python list."""
        return list(self)

    def __repr__(self):
        return f"LinkedList({self.to_list()!r})"


